// The two clamps and the wire's clamp must all say 90 minutes. They are
// separate constants on purpose — RelayGuard must not take the decoder's word
// for a duration — so the agreement is asserted rather than assumed.
static_assert(kRelayHardCapMs == static_cast<uint32_t>(proto::kRelayHardCapSeconds) * 1000UL,
              "the relay hard cap and the protocol's wire clamp have drifted apart");

// hal::IButtonPort numbers courts 0-3 and duration slots 4-7; proto::Key spells
// the same eight in the same order. The `!BTN` frame is built by casting one to
// the other, so the two orders being identical is load-bearing.
static_assert(static_cast<uint8_t>(proto::Key::CourtA) == hal::kCourtButtonBase,
              "proto::Key and hal button channels must agree on where the courts start");
static_assert(static_cast<uint8_t>(proto::Key::Slot1) == hal::kDurationButtonBase,
              "proto::Key and hal button channels must agree on where the duration slots start");
static_assert(static_cast<uint8_t>(proto::Key::Slot4) + 1U == hal::kButtonCount,
              "proto::Key and hal button channels must cover the same eight buttons");

// The wire addresses four rows whatever panel is fitted, and the LAYOUT is what
// decides how many are drawn. The assertion lives HERE, on the device side that
// knows about both, for the same reason bridgelogic/RosterTokenFits.h does.
static_assert(hal::kDisplayRows <= proto::kMaxRows, "the panel has more rows than the protocol can address");

// The ceiling's upper bound is the frame clamp: no setting may let a screen
// outlive the two minutes no single frame may.
static_assert(kCfgKeys[static_cast<uint8_t>(Cfg::Cap)].min == kCapMinMinutes &&
                  kCfgKeys[static_cast<uint8_t>(Cfg::Cap)].max == kCapMaxMinutes &&
                  kCfgKeys[static_cast<uint8_t>(Cfg::Cap)].boot == kCapDefaultMinutes,
              "the CAP key and RelayGuard's cap bounds have drifted apart");

/// Decimal parse of an argument the decoder has already validated and clamped.
/// Saturating, stopping at the first non-digit: belt and braces, because
/// RelayGuard's independence is only real if nothing on this path assumes the
/// bytes came from a well-behaved peer.
uint32_t parseU32(const char* text) {
  uint32_t value = 0U;
  for (size_t i = 0U; text[i] != '\0'; ++i) {
    const char c = text[i];
    if (c < '0' || c > '9') {
      break;
    }
    const uint32_t digit = static_cast<uint32_t>(c - '0');
    if (value > (UINT32_MAX - digit) / 10U) {
      return UINT32_MAX;
    }
    value = value * 10U + digit;
  }
  return value;
}

/// "-" (no opinion) or the decoder-clamped number.
int32_t opinionOf(const char* text) {
  if (text[0] == '-' || text[0] == '\0') {
    return proto::kNoOpinion;
  }
  const uint32_t v = parseU32(text);
  return v > 0x7FFFFFFFUL ? 0x7FFFFFFF : static_cast<int32_t>(v);
}

uint8_t hexDigit(char c) {
  return static_cast<uint8_t>(c <= '9' ? c - '0' : c - 'A' + 10);
}

uint16_t parseHex4(const char* text) {
  uint16_t v = 0U;
  for (uint8_t i = 0U; i < 4U && text[i] != '\0'; ++i) {
    v = static_cast<uint16_t>((v << 4) | hexDigit(text[i]));
  }
  return v;
}

/// The tag of a tagged v2 relay/auth frame (its optional last argument), or
/// kNoTag for the v2 form.
uint8_t tagOf(const proto::Frame& frame, uint8_t index) {
  return frame.argCount() > index ? static_cast<uint8_t>(parseU32(frame.arg(index))) : proto::kNoTag;
}

bool isV3Verb(proto::Verb v) {
  return static_cast<uint8_t>(v) >= static_cast<uint8_t>(proto::Verb::Rw);
}

