CourtBox::CourtBox(const CourtPorts& ports, proto::LegacyDialect legacy)
    : scanner_(ports.scanner), buttons_(ports.buttons), bridge_(ports.bridge), clock_(ports.clock),
      relayPort_(ports.relay), display_(ports.display), settings_(), relays_(ports.relay),
      screens_(ports.display, settings_), panel_(ports.buttons), scan_(), baud_(), auth_(),
      rx_(proto::Link::Downlink, legacy), uptime_(), stateDue_(), lastMask_(0U), stateNow_(false), txBuf_(),
      txQueue_(), txHead_(0U), txCount_(0U), txDropped_(0U), rxErrors_(0U), unauthorised_(0U),
      oversizeScans_(0U), corruptScans_(0U), lastScanRejects_(0U), lastScanByteMs_(0U), lastRxMs_(0U),
      livePeriodS_(0U), liveSeen_(false), bridgeAlive_(true), lastTag_(), lastTagAtMs_(), hwSent_(),
      hwDue_(true) {
}

void CourtBox::begin() {
  relays_.allOff();
  auth_.disarm();
  scan_.reset();
  rx_.reset();
  const uint32_t now = clock_.nowMs();
  uptime_.seed(now);
  stateDue_.arm(now, kStateIntervalMs);
  lastMask_ = 0U;
  for (uint8_t i = 0U; i < 5U; ++i) {
    lastTag_[i] = proto::kNoTag;
  }
  lastRxMs_ = now;
  screens_.begin(now);
  screens_.setBridgeAlive(bridgeAlive_, now);
}

void CourtBox::boot(uint8_t resetCause) {
  // Every setting back to its boot default: the bridge re-sends the set after
  // the `!BOOT` below, before any relay frame.
  settings_.reset();
  relayPort_.setPolarity(settings_.relayActiveLow() ? hal::RelayPolarity::kActiveLow
                                                    : hal::RelayPolarity::kActiveHigh);
  static_cast<void>(relays_.setCapMinutes(settings_.get(Cfg::Cap)));
  baud_.configure(static_cast<uint8_t>(settings_.get(Cfg::Sbaud)));
  scanner_.setBaud(baud_.rate());
  display_.setAddress(static_cast<uint8_t>(settings_.get(Cfg::Lcda)));
  liveSeen_ = false;
  livePeriodS_ = 0U;
  bridgeAlive_ = true;
  begin();
  const uint32_t bootMs = clock_.nowMs();

  uint8_t held = 0U;
  for (uint8_t i = 0U; i < hal::kButtonCount; ++i) {
    if (buttons_.read(i) == hal::kButtonPressedLevel) {
      held = static_cast<uint8_t>(held | buttonBit(i));
    }
  }
  static_cast<void>(sendFrame(proto::Frame::boot(fw::kFirmwareVersion, resetCause, held)));
  stateNow_ = true;
  publishState(bootMs);
  hwDue_ = true;
  flushTx();
}

void CourtBox::poll() {
  // Once. Every sub-step is evaluated against the same instant.
  const uint32_t now = clock_.nowMs();
  uptime_.tick(now);

  drainBridge(now);
  drainScanner(now);
  expireScanLine(now);
  pollButtons(now);
  releaseExpired(now);
  noteAuthLapse(now);
  watchBridge(now);
  flushTx();
  // The paint is budgeted (8 ms at most); the link is drained again after it,
  // so no pass leaves the 64-byte RX ring unread for longer than ~10 ms.
  screens_.poll(relays_, now);
  drainBridge(now);
  if (screens_.takeCeilingEvent()) {
    static_cast<void>(sendFrame(proto::Frame::evt("CEIL", "")));
  }
  reportHardware();
  publishState(now);
  flushTx();
}

// --- one pass --------------------------------------------------------------

void CourtBox::drainBridge(uint32_t nowMs) {
  uint8_t byte = 0U;
  for (uint16_t i = 0U; i < kBytesPerPass && bridge_.read(byte); ++i) {
    if (!rx_.feed(static_cast<char>(byte))) {
      continue;
    }
    proto::Decoder::Result result;
    while (rx_.pop(result)) {
      handleResult(result, nowMs);
    }
  }
}

void CourtBox::drainScanner(uint32_t nowMs) {
  uint8_t byte = 0U;
  for (uint16_t i = 0U; i < kBytesPerPass && scanner_.read(byte); ++i) {
    lastScanByteMs_ = nowMs;
    const bool complete = scan_.feed(byte);
    reportScanRejects();
    if (scan_.takeGarbage() && baud_.garbage(screens_.onLanding())) {
      scanner_.setBaud(baud_.rate());
      scan_.reset();
    }
    if (complete) {
      completeScan(nowMs);
    }
  }
}

void CourtBox::completeScan(uint32_t nowMs) {
  baud_.cleanLine();
  const proto::Frame frame = proto::Frame::scan(scan_.code());
  if (frame.empty()) {
    // Unreachable while ScanAssembler's cap is proto::kMaxArgLen; kept because
    // a truncated member code identifies SOMEBODY ELSE.
    if (oversizeScans_ < UINT16_MAX) {
      ++oversizeScans_;
    }
    sendScanReject("OVERSIZE", oversizeScans_);
    return;
  }
  static_cast<void>(sendFrame(frame));
  // A completed scan pre-empts whatever is on the glass, from the Mega's own
  // constant buffer (FWM-07), and restarts the ceiling: a scan is a new member.
  screens_.scanCompleted(nowMs);
}

/// v3 rule 6: a line ends on CR, LF or SGAP ms of idle (FWM-14, HW-5).
void CourtBox::expireScanLine(uint32_t nowMs) {
  if (!scan_.partial() || tb::since(nowMs, lastScanByteMs_) < settings_.get(Cfg::Sgap)) {
    return;
  }
  const bool complete = scan_.gap(settings_.get(Cfg::Ssuf) == 1U);
  if (scan_.takeGarbage() && baud_.garbage(screens_.onLanding())) {
    scanner_.setBaud(baud_.rate());
    scan_.reset();
  }
  if (complete) {
    completeScan(nowMs);
  }
}

void CourtBox::reportScanRejects() {
  const uint16_t rejected = scan_.rejectedLines();
  if (rejected == lastScanRejects_) {
    return;
  }
  lastScanRejects_ = rejected;
  if (scan_.lastReject() == ScanReject::TooLong) {
    if (oversizeScans_ < UINT16_MAX) {
      ++oversizeScans_;
    }
    sendScanReject("OVERSIZE", oversizeScans_);
    return;
  }
  if (corruptScans_ < UINT16_MAX) {
    ++corruptScans_;
  }
  sendScanReject("SCANJUNK", corruptScans_);
}

void CourtBox::sendScanReject(const char* name, uint16_t count) {
  // The member sees nothing for either: both are faults of the reader, and
  // the club finds out from the fault, which is where the fix is.
  proto::Arg digits;
  digits.setU32(count);
  static_cast<void>(sendFrame(proto::Frame::evt(name, digits.c_str())));
}

/// Presses (v3 rules 2 and 4, HW-7). A press is forwarded or dropped; it never
/// touches a screen's deadline. An armed press is always forwarded; an unarmed
/// one exactly when its `KEYS` bit is set. A dropped press is counted and ENDS
/// the overlay with the hint. A forwarded press the bridge does not answer
/// within 1.5 s gets the Mega's own hint; one the link could not carry gets it
/// at once.
void CourtBox::pollButtons(uint32_t nowMs) {
  const uint8_t pressed = panel_.poll(nowMs);
  if (pressed == 0U) {
    return;
  }
  const bool armed = auth_.allows(nowMs);
  const uint8_t forwardable = armed ? 0xFFU : settings_.keys();
  bool forwarded = false;
  bool unsent = false;
  bool dropped = false;
  for (uint8_t i = 0U; i < hal::kButtonCount; ++i) {
    if ((pressed & buttonBit(i)) == 0U) {
      continue;
    }
    if ((forwardable & buttonBit(i)) == 0U) {
      dropped = true;
    } else if (sendFrame(proto::Frame::btn(static_cast<proto::Key>(i)))) {
      forwarded = true;
    } else {
      unsent = true;
    }
  }
  if (dropped && unauthorised_ < UINT16_MAX) {
    ++unauthorised_;
  }
  if (forwarded) {
    screens_.pressForwarded(nowMs);
  }
  if (unsent) {
    screens_.pressUnsent(nowMs);
  } else if (dropped) {
    screens_.droppedPress(nowMs);
  }
}

void CourtBox::releaseExpired(uint32_t nowMs) {
  const uint8_t released = relays_.tick(nowMs);
  if (released == 0U) {
    return;
  }
  const uint8_t capped = relays_.lastCapReleased();
  for (uint8_t i = 0U; i < hal::kRelayChannelCount; ++i) {
    if ((released & relayBit(i)) != 0U) {
      sendCourtEvent((capped & relayBit(i)) != 0U ? "CAPOFF" : "AUTOOFF", i);
    }
  }
  stateNow_ = true;
}

/// Bridge liveness (v3). After a `!LIVE`, dead when no valid frame for three
/// periods plus a second; before any, after 330 s of silence. The relay
/// deadlines, the cap and the ceiling never depended on the bridge.
void CourtBox::watchBridge(uint32_t nowMs) {
  if (!bridgeAlive_) {
    return;
  }
  const uint32_t limit = liveSeen_
                             ? static_cast<uint32_t>(static_cast<uint32_t>(livePeriodS_) * 3000UL + 1000UL)
                             : kLegacyLivenessMs;
  if (tb::since(nowMs, lastRxMs_) > limit) {
    bridgeAlive_ = false;
    screens_.setBridgeAlive(false, nowMs);
  }
}

void CourtBox::noteAuthLapse(uint32_t nowMs) {
  if (auth_.lapsed(nowMs)) {
    static_cast<void>(sendFrame(proto::Frame::evt("AUTHEXPIRED", "")));
  }
}

/// `!HW` once the LCD is up (the first poll after boot()), after every
/// `!DIAG`, and whenever one of the facts changes.
void CourtBox::reportHardware() {
  const uint8_t now[5] = {display_.address(), static_cast<uint8_t>(settings_.get(Cfg::Rpol)),
                          baud_.reported(), static_cast<uint8_t>(settings_.get(Cfg::Ssuf)), settings_.keys()};
  bool changed = hwDue_;
  for (uint8_t i = 0U; i < 5U; ++i) {
    changed = changed || now[i] != hwSent_[i];
  }
  if (!changed) {
    return;
  }
  if (sendFrame(proto::Frame::hw(now[0], now[1], now[2], now[3], now[4]))) {
    hwDue_ = false;
    for (uint8_t i = 0U; i < 5U; ++i) {
      hwSent_[i] = now[i];
    }
  }
}

void CourtBox::publishState(uint32_t nowMs) {
  const uint8_t mask = relays_.mask();
  if (!stateNow_ && mask == lastMask_ && !stateDue_.expired(nowMs)) {
    return;
  }
  uint16_t remaining[hal::kRelayChannelCount];
  for (uint8_t i = 0U; i < hal::kRelayChannelCount; ++i) {
    remaining[i] = relays_.remainingSeconds(i, nowMs);
  }
  if (sendFrame(proto::Frame::state(mask, remaining))) {
    lastMask_ = mask;
    stateNow_ = false;
    stateDue_.arm(nowMs, kStateIntervalMs);
  }
}

/// As much of the uplink queue as the UART ring has room for. Bytes leave in
/// order, so a frame split across passes is still one frame on the wire.
void CourtBox::flushTx() {
  if (txCount_ == 0U || !bridge_.connected()) {
    return;
  }
  size_t room = bridge_.writable();
  while (room > 0U && txCount_ > 0U) {
    const uint16_t contiguous = static_cast<uint16_t>(kTxQueueBytes - txHead_);
    uint16_t n = txCount_ < contiguous ? txCount_ : contiguous;
    n = static_cast<uint16_t>(n < room ? n : room);
    const size_t wrote = bridge_.write(txQueue_ + txHead_, n);
    if (wrote == 0U) {
      return;
    }
    txHead_ = static_cast<uint16_t>((txHead_ + wrote) % kTxQueueBytes);
    txCount_ = static_cast<uint16_t>(txCount_ - wrote);
    room -= wrote;
  }
}

// --- inbound ---------------------------------------------------------------

void CourtBox::handleResult(const proto::Decoder::Result& result, uint32_t nowMs) {
  if (result.isFrame()) {
    // Any valid frame is the bridge alive; one after a dead verdict revives it
    // and says so, and the bridge then re-sends the settings and landing.
    lastRxMs_ = nowMs;
    if (!bridgeAlive_) {
      bridgeAlive_ = true;
      screens_.setBridgeAlive(true, nowMs);
      static_cast<void>(sendFrame(proto::Frame::evt("LIVE", "1")));
    }
    handleFrame(result.frame, nowMs);
    return;
  }
  if (rxErrors_ < UINT16_MAX) {
    ++rxErrors_;
  }
  reportDecodeError(result.error);
}

void CourtBox::handleFrame(const proto::Frame& frame, uint32_t nowMs) {
  const proto::Verb verb = frame.verb();
  if (isV3Verb(verb)) {
    handleV3Frame(frame, nowMs);
  } else if (verb == proto::Verb::On) {
    applyOn(frame, nowMs);
  } else if (verb == proto::Verb::Off) {
    applyOff(frame, nowMs);
  } else if (verb == proto::Verb::Ext) {
    applyExt(frame, nowMs);
  } else if (ScreenBuffer::owns(verb)) {
    applyScreen(frame, nowMs);
  } else if (verb == proto::Verb::Auth) {
    applyAuth(frame, nowMs);
  } else if (verb == proto::Verb::Rst) {
    begin();
  } else if (verb == proto::Verb::Ping) {
    answerPing();
  } else {
    // A well-formed uplink verb arriving on the downlink: what a crossed
    // TX/RX pair looks like, worth saying out loud.
    static_cast<void>(sendFrame(proto::Frame::err(proto::DecodeError::BadVerb)));
  }
}

void CourtBox::handleV3Frame(const proto::Frame& frame, uint32_t nowMs) {
  const proto::Verb verb = frame.verb();
  if (ScreenBuffer::owns(verb)) {
    applyV3Screen(frame, nowMs);
  } else if (verb == proto::Verb::Want) {
    applyWant(frame, nowMs);
  } else if (verb == proto::Verb::Cfg) {
    applyCfg(frame);
  } else if (verb == proto::Verb::Live) {
    liveSeen_ = true;
    livePeriodS_ = static_cast<uint8_t>(parseU32(frame.arg(0)));
  } else {
    static_cast<void>(sendFrame(proto::Frame::err(proto::DecodeError::BadVerb)));
  }
}

void CourtBox::answerPing() {
  static_cast<void>(sendFrame(
      proto::Frame::pong(fw::kFirmwareVersion, uptimeSeconds(), txDropped_, rxErrors_, unauthorised_)));
  const uint16_t counters[5] = {display_.timeouts(),
                                static_cast<uint16_t>(screens_.reinits() + display_.recoveries()),
                                bridge_.rxOverruns(), screens_.ceilings(), relays_.capOffCount()};
  static_cast<void>(sendFrame(proto::Frame::diag(counters)));
  hwDue_ = true;
}

void CourtBox::reportDecodeError(proto::DecodeError error) {
  if (error == proto::DecodeError::BadFrame || error == proto::DecodeError::Overrun) {
    static_cast<void>(sendFrame(proto::Frame::evt(proto::errorName(error), "RX")));
    return;
  }
  if (error != proto::DecodeError::None) {
    static_cast<void>(sendFrame(proto::Frame::err(error)));
  }
}

bool CourtBox::courtOf(const proto::Frame& frame, uint8_t& channel) {
  proto::Court court = proto::Court::A;
  if (!proto::courtFromChar(frame.arg(0)[0], court)) {
    static_cast<void>(sendFrame(proto::Frame::err(proto::DecodeError::NoCourt)));
    return false;
  }
  channel = static_cast<uint8_t>(court);
  return true;
}

bool CourtBox::duplicate(uint8_t slot, uint8_t tag, uint32_t nowMs) {
  if (tag == proto::kNoTag || lastTag_[slot] != tag ||
      tb::since(nowMs, lastTagAtMs_[slot]) > kDuplicateWindowMs) {
    return false;
  }
  ack(tag, proto::AckCode::Duplicate);
  return true;
}

void CourtBox::remember(uint8_t slot, uint8_t tag, uint32_t nowMs) {
  if (tag != proto::kNoTag) {
    lastTag_[slot] = tag;
    lastTagAtMs_[slot] = nowMs;
  }
}

void CourtBox::ack(uint8_t tag, proto::AckCode code) {
  if (tag != proto::kNoTag) {
    static_cast<void>(sendFrame(proto::Frame::ack(tag, code)));
  }
}

void CourtBox::applyOn(const proto::Frame& frame, uint32_t nowMs) {
  uint8_t channel = 0U;
  if (!courtOf(frame, channel)) {
    return;
  }
  const uint8_t tag = tagOf(frame, 2U);
  if (duplicate(channel, tag, nowMs)) {
    return;
  }
  const bool wasLit = relayPort_.isOn(channel);
  // Never shortens a lit court (FSF-12), and restarts the authorisation clock.
  static_cast<void>(relays_.on(channel, parseU32(frame.arg(1)), nowMs));
  remember(channel, tag, nowMs);
  ack(tag, proto::AckCode::Applied);
  if (!wasLit) {
    screens_.lightsOn(nowMs);
  }
  stateNow_ = true;
  publishState(nowMs);
}

void CourtBox::applyOff(const proto::Frame& frame, uint32_t nowMs) {
  uint8_t channel = 0U;
  if (!courtOf(frame, channel)) {
    return;
  }
  const uint8_t tag = tagOf(frame, 1U);
  if (duplicate(channel, tag, nowMs)) {
    return;
  }
  static_cast<void>(relays_.off(channel));
  remember(channel, tag, nowMs);
  ack(tag, proto::AckCode::Applied);
  // Every commanded release is reported, so an early release is accounted for
  // as the time actually used.
  sendCourtEvent("OFF", channel);
  stateNow_ = true;
}

void CourtBox::applyExt(const proto::Frame& frame, uint32_t nowMs) {
  uint8_t channel = 0U;
  if (!courtOf(frame, channel)) {
    return;
  }
  const uint8_t tag = tagOf(frame, 2U);
  if (duplicate(channel, tag, nowMs)) {
    return;
  }
  if (!relays_.extend(channel, parseU32(frame.arg(1)), nowMs)) {
    // The relay is open, or the cap locked it: refused.
    if (tag == proto::kNoTag) {
      static_cast<void>(sendFrame(proto::Frame::err(proto::DecodeError::BadArg)));
    } else {
      ack(tag, proto::AckCode::Refused);
    }
    return;
  }
  remember(channel, tag, nowMs);
  ack(tag, proto::AckCode::Applied);
  // The new deadline at once (Mega 2.1.0).
  stateNow_ = true;
  publishState(nowMs);
}

void CourtBox::applyAuth(const proto::Frame& frame, uint32_t nowMs) {
  const uint8_t tag = tagOf(frame, 1U);
  if (duplicate(kAuthSlot, tag, nowMs)) {
    return;
  }
  auth_.arm(nowMs, parseU32(frame.arg(0)));
  remember(kAuthSlot, tag, nowMs);
  ack(tag, proto::AckCode::Applied);
}

/// `!WANT,<tag>,<a>,<b>,<c>,<d>`: ensure each relay with an opinion is lit for
/// at least that long. Lights or lengthens; never opens; a capped relay
/// refuses. Always followed by `!STATE`.
void CourtBox::applyWant(const proto::Frame& frame, uint32_t nowMs) {
  const uint8_t tag = static_cast<uint8_t>(parseU32(frame.arg(0)));
  bool refused = false;
  bool lit = false;
  for (uint8_t i = 0U; i < hal::kRelayChannelCount; ++i) {
    const int32_t want = opinionOf(frame.arg(static_cast<uint8_t>(i + 1U)));
    if (want == proto::kNoOpinion) {
      continue;
    }
    bool closedNow = false;
    if (relays_.want(i, static_cast<uint32_t>(want), nowMs, closedNow) == WantResult::Refused) {
      refused = true;
    }
    lit = lit || closedNow;
  }
  if (lit) {
    screens_.lightsOn(nowMs);
  }
  ack(tag, refused ? proto::AckCode::Refused : proto::AckCode::Applied);
  stateNow_ = true;
  publishState(nowMs);
}

void CourtBox::applyCfg(const proto::Frame& frame) {
  const uint8_t tag = static_cast<uint8_t>(parseU32(frame.arg(0)));
  const proto::AckCode code = settings_.apply(frame.arg(1), parseU32(frame.arg(2)));
  if (code == proto::AckCode::Applied) {
    applySideEffects(settings_.lastApplied());
  }
  ack(tag, code);
}

/// What a setting changes outside the screens (which read the settings on
/// every compose).
void CourtBox::applySideEffects(Cfg key) {
  if (key == Cfg::Cap) {
    static_cast<void>(relays_.setCapMinutes(settings_.get(Cfg::Cap)));
  } else if (key == Cfg::Rpol) {
    // Every closed relay re-driven at the new level; an open one stays an
    // input (HW-1). A wrong level therefore fails dark, never lit.
    relayPort_.setPolarity(settings_.relayActiveLow() ? hal::RelayPolarity::kActiveLow
                                                      : hal::RelayPolarity::kActiveHigh);
  } else if (key == Cfg::Lcda) {
    display_.setAddress(static_cast<uint8_t>(settings_.get(Cfg::Lcda)));
  } else if (key == Cfg::Sbaud) {
    baud_.configure(static_cast<uint8_t>(settings_.get(Cfg::Sbaud)));
    scanner_.setBaud(baud_.rate());
    scan_.reset();
  }
}

void CourtBox::applyScreen(const proto::Frame& frame, uint32_t nowMs) {
  const proto::Verb verb = frame.verb();
  if (verb == proto::Verb::Lcd) {
    screens_.overlay(frame.arg(0), frame.arg(1), nowMs);
  } else if (verb == proto::Verb::Row) {
    screens_.stageRow(static_cast<uint8_t>(parseU32(frame.arg(0))), frame.arg(1));
  } else if (verb == proto::Verb::Show) {
    screens_.show(parseU32(frame.arg(0)), static_cast<uint8_t>(parseU32(frame.arg(1))), nowMs);
  } else if (verb == proto::Verb::Idle) {
    screens_.setLink(static_cast<uint8_t>(parseU32(frame.arg(0))), frame.arg(1), nowMs);
  } else {
    int16_t numbers[hal::kRelayChannelCount];
    for (uint8_t i = 0U; i < hal::kRelayChannelCount; ++i) {
      numbers[i] = static_cast<int16_t>(parseU32(frame.arg(i)));
    }
    screens_.setCourtNumbers(numbers);
  }
}

void CourtBox::applyV3Screen(const proto::Frame& frame, uint32_t nowMs) {
  const proto::Verb verb = frame.verb();
  if (verb == proto::Verb::Rw) {
    screens_.stageSegment(static_cast<uint8_t>(parseU32(frame.arg(0))),
                          static_cast<uint8_t>(parseU32(frame.arg(1))),
                          static_cast<uint8_t>(parseU32(frame.arg(2))), frame.arg(3));
  } else if (verb == proto::Verb::Cmt) {
    const uint8_t seq = static_cast<uint8_t>(parseU32(frame.arg(0)));
    const proto::AckCode code =
        screens_.commit(seq, static_cast<uint8_t>(parseU32(frame.arg(1))), parseU32(frame.arg(2)),
                        static_cast<uint8_t>(parseU32(frame.arg(3))), parseHex4(frame.arg(4)), nowMs);
    static_cast<void>(sendFrame(proto::Frame::ackScreen(seq, code)));
  } else if (verb == proto::Verb::Land) {
    int32_t seconds[hal::kRelayChannelCount];
    for (uint8_t i = 0U; i < hal::kRelayChannelCount; ++i) {
      seconds[i] = opinionOf(frame.arg(i));
    }
    screens_.setLand(seconds, nowMs);
  } else {
    screens_.setNote(parseU32(frame.arg(0)), frame.arg(1), nowMs);
  }
}

// --- outbound --------------------------------------------------------------

bool CourtBox::sendFrame(const proto::Frame& frame) {
  const size_t len = proto::encode(frame, txBuf_, sizeof(txBuf_));
  if (len == 0U || len > static_cast<size_t>(kTxQueueBytes - txCount_)) {
    if (txDropped_ < UINT16_MAX) {
      ++txDropped_;
    }
    return false;
  }
  for (size_t i = 0U; i < len; ++i) {
    txQueue_[(txHead_ + txCount_) % kTxQueueBytes] = static_cast<uint8_t>(txBuf_[i]);
    ++txCount_;
  }
  return true;
}

void CourtBox::sendCourtEvent(const char* name, uint8_t channel) {
  const char detail[2] = {proto::courtChar(static_cast<proto::Court>(channel)), '\0'};
  static_cast<void>(sendFrame(proto::Frame::evt(name, detail)));
}

